<?php
require __DIR__.'/app.php'; header('Cache-Control: no-store');
if(empty($_SESSION['user_id'])) {header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST') {verify_csrf();unset($_SESSION['user_id']);session_regenerate_id(true);header('Location: login.php');exit;}
try {$stmt=db()->prepare('SELECT name,email,created_at FROM users WHERE id=?');$stmt->execute([$_SESSION['user_id']]);$user=$stmt->fetch();if(!$user){unset($_SESSION['user_id']);header('Location: login.php');exit;}}
catch(Throwable $e){error_log($e->getMessage());http_response_code(503);exit('Your account is temporarily unavailable. Please try again later.');}

$initial = function_exists('mb_substr') ? mb_substr($user['name'],0,1,'UTF-8') : substr($user['name'],0,1);
$appointments=[]; $appointmentsError=false;
try {
 $stmt=db()->prepare('SELECT id,service,vehicle,preferred_date,status,notes,created_at FROM bookings WHERE user_id=? ORDER BY created_at DESC,id DESC');
 $stmt->execute([$_SESSION['user_id']]); $appointments=$stmt->fetchAll();
} catch(Throwable $e) { error_log($e->getMessage()); $appointmentsError=true; }
$appointmentCounts=array_fill_keys(['pending','confirmed','completed','cancelled'],0);
foreach($appointments as $item)if(isset($appointmentCounts[$item['status']]))$appointmentCounts[$item['status']]++;
